function fail(message) {
  return {
    success: false,
    message,
    payload: null
  };
}

// src/app.ts
var WINDOW_MS = 60000;
var MAX_REQUESTS = 60;
var rateLimitStore = new I({
  max: 1e4,
  ttl: WINDOW_MS
});
var app = new Hono2().basePath("/api");
app.use(cors({
  origin: [
    "http://localhost:5173",
    "http://localhost:3000",
    "https://liutentor.se"
  ]
}));
app.use(async (c, next) => {
  const ip = c.req.header("x-forwarded-for")?.split(",")[0].trim() ?? c.req.header("x-real-ip") ?? "unknown";
  const now = Date.now();
  const entry = rateLimitStore.get(ip);
  if (!entry || now >= entry.resetAt) {
    rateLimitStore.set(ip, { count: 1, resetAt: now + WINDOW_MS });
    return next();
  }
  if (entry.count >= MAX_REQUESTS) {
    const retryAfter = Math.ceil((entry.resetAt - now) / 1000);
    c.header("Retry-After", String(retryAfter));
    return c.json(fail("Too many requests"), 429);
  }
  entry.count += 1;
  return next();
});
app.onError((err, c) => {
  if (err instanceof HTTPException) {
    return c.json(fail(err.message), err.status);
  }
  console.error(err);
  return c.json(fail("Internal server error"), 500);
});
app.use(supabaseMiddleware);
app.route("/", chat_routes_default);
app.route("/", quiz_route_default);
var app_default = {
  port: process.env.PORT || 3001,
  fetch: app.fetch,
  idleTimeout: 120
};
export {
  app_default as default
};
